    batches = {"code": [], "test": [], "docs": [], "config": []}
    config_names = {"package.json", "package-lock.json", "tsconfig.json", "next.config.js", ".eslintrc.json"}

    for path in files:
        name = path.split('/')[-1]
        if '/test/' in path or '.test.' in path or '.spec.' in path:
            batches["test"].append(path)
        elif path.startswith('docs/') or path.endswith('.md'):
            batches["docs"].append(path)
        elif name in config_names or path.startswith('.github/'):
            batches["config"].append(path)
        else:
            batches["code"].append(path)
    return batches

