    conflicts = []
    for a in branch_a:
        for b in branch_b:
            if a["file"] != b["file"]:
                continue
            if max(a["start"], b["start"]) <= min(a["end"], b["end"]):
                conflicts.append(a["file"])
    unique = sorted(set(conflicts))
    return {"risk": "high" if unique else "low", "files": unique}

